import random

def strategy(history, rng):
    if not history:
        return 'C'
    n = len(history)
    # Last few moves
    last_self, last_opp = history[-1]
    # Cooperation rate of both sides
    my_c = sum(1 for a, b in history if a == 'C')
    op_c = sum(1 for a, b in history if b == 'C')
    my_rate = my_c / n
    op_rate = op_c / n
    # Detect defection streak
    opp_def = 0
    for a, b in reversed(history):
        if b == 'D':
            opp_def += 1
        else:
            break
    my_def = 0
    for a, b in reversed(history):
        if a == 'D':
            my_def += 1
        else:
            break
    # End game: last ~20 rounds exploit if opponent is cooperative
    remaining = 100 - n
    if remaining <= 15:
        if op_rate > 0.6:
            return 'D'
        if op_rate < 0.3:
            return 'D'
        return last_opp
    # If opponent just defected repeatedly, retaliate
    if opp_def >= 2:
        return 'D'
    if opp_def == 1:
        # Tit-for-tat with forgiveness: defect once
        return 'D'
    # Opponent cooperated last move
    # If we've been defecting too much, return to cooperation
    if my_def >= 3:
        return 'C'
    # Exploit a highly cooperative opponent occasionally
    if op_rate > 0.85 and n > 10:
        if rng.random() < 0.1:
            return 'D'
    if op_rate < 0.4 and n > 10:
        return 'D'
    return 'C'
